import { describe, it, expectTypeOf } from "vitest";
import {
  defineHandler,
  getQuery,
  readBody,
  readValidatedBody,
  getValidatedQuery,
  defineValidatedHandler,
  defineWebSocketHandler,
  defineLazyEventHandler,
  defineRoute,
  toEventHandler,
  withBase,
  requireBasicAuth,
} from "../../src/index.ts";
import {
  appendHeaders,
  appendResponseHeaders,
  defineEventHandler,
  sendRedirect,
} from "../../src/_deprecated.ts";
