    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const config: SessionConfig = {
        name: "h3-chunk-err",
        password: sessionConfig.password,
        idleTimeout: 60,
      };
      const big = "x".repeat(5000);
      t.app.get("/chunk-err-ok", async (event) => {
