describe("extraUnsealPasswords", () => {
  const createdAt = 1_700_000_000_000;
  const sealedWith = (password: string, data: Record<string, unknown> = {}, id = "rot-1") =>
    seal({ id, createdAt, data }, password, sealDefaults);
  // Value of a named cookie in a response, decoded back to the sealed string
  const sealedCookie = (res: Response, name: string) =>
    decodeURIComponent(
      res.headers
        .getSetCookie()
        .find((c) => c.startsWith(`${name}=`))!
        .split(";")[0]
        .slice(name.length + 1),
    );

  it("opens a session sealed with an extra password", async () => {
    const config: SessionConfig = { name: "h3-extra", password: OLD, extraUnsealPasswords: [NEW] };
    t.app.get("/extra", async (event) => {
      const session = await getSession(event, config);
      return { id: session.id, createdAt: session.createdAt, data: session.data };
    });
    const res = await t.fetch("/extra", {
      headers: { Cookie: `h3-extra=${await sealedWith(NEW, { foo: "bar" })}` },
    });
    expect(await res.json()).toEqual({ id: "rot-1", createdAt, data: { foo: "bar" } });
  });

  it("tries extra passwords in declared order after password", async () => {
    const config: SessionConfig = {
      name: "h3-order",
      password: OLD,
      extraUnsealPasswords: [OTHER, NEW],
    };
    t.app.get("/order", async (event) => {
      const session = await getSession(event, config);
      return { id: session.id };
    });
    const fromExtra = await t.fetch("/order", {
      headers: { Cookie: `h3-order=${await sealedWith(NEW)}` },
    });
    expect(await fromExtra.json()).toEqual({ id: "rot-1" });
    const fromPassword = await t.fetch("/order", {
      headers: { Cookie: `h3-order=${await sealedWith(OLD)}` },
    });
    expect(await fromPassword.json()).toEqual({ id: "rot-1" });
  });

  it("reseals a written session with password only", async () => {
    const config: SessionConfig = { name: "h3-rot", password: OLD, extraUnsealPasswords: [NEW] };
    t.app.get("/rot-write", async (event) => {
      const session = await updateSession(event, config, { touched: true });
      return { id: session.id, data: session.data };
    });
    const res = await t.fetch("/rot-write", {
      headers: { Cookie: `h3-rot=${await sealedWith(NEW, { foo: "bar" })}` },
    });
    expect(await res.json()).toEqual({ id: "rot-1", data: { foo: "bar", touched: true } });
    const resealed = sealedCookie(res, "h3-rot");
    await expect(unseal(resealed, OLD, sealDefaults)).resolves.toMatchObject({
      id: "rot-1",
      data: { foo: "bar", touched: true },
    });
    await expect(unseal(resealed, NEW, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("clears a session opened by an extra password", async () => {
    const config: SessionConfig = {
      name: "h3-rot-clear",
      password: OLD,
      extraUnsealPasswords: [NEW],
    };
    t.app.get("/rot-clear", async (event) => {
      await getSession(event, config);
      await clearSession(event, config);
      return { cleared: true };
    });
    const res = await t.fetch("/rot-clear", {
      headers: { Cookie: `h3-rot-clear=${await sealedWith(NEW)}` },
    });
    const cookies = res.headers.getSetCookie().filter((c) => c.startsWith("h3-rot-clear="));
    expect(cookies).toHaveLength(1);
    expect(cookies[0]).toContain("Max-Age=0");
  });

  it("reseals a session slid by idleTimeout with password only", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const sealed = await seal(
        { id: "slide-1", createdAt: t0, data: { foo: "bar" } },
        NEW,
        sealDefaults,
      );
      const config: SessionConfig = {
        name: "h3-slide",
        password: OLD,
        extraUnsealPasswords: [NEW],
        idleTimeout: 60,
      };
      t.app.get("/slide", async (event) => {
        const session = await getSession(event, config);
        return { id: session.id };
      });
      // Past half the idle window, so the read reseals the cookie
      vi.setSystemTime(t0 + 45_000);
      const res = await t.fetch("/slide", { headers: { Cookie: `h3-slide=${sealed}` } });
      expect(await res.json()).toEqual({ id: "slide-1" });
      const resealed = sealedCookie(res, "h3-slide");
      await expect(unseal(resealed, OLD, sealDefaults)).resolves.toMatchObject({
        id: "slide-1",
        data: { foo: "bar" },
      });
      await expect(unseal(resealed, NEW, sealDefaults)).rejects.toThrow("Bad hmac value");
    } finally {
      vi.useRealTimers();
    }
  });

  it("treats a session sealed with an unlisted password as new", async () => {
    const config: SessionConfig = {
      name: "h3-unlisted",
      password: OLD,
      extraUnsealPasswords: [NEW],
    };
    t.app.get("/unlisted", async (event) => {
      const session = await getSession(event, config);
      return { id: session.id, data: session.data };
    });
    const res = await t.fetch("/unlisted", {
      headers: { Cookie: `h3-unlisted=${await sealedWith(OTHER, { secret: "x" }, "stranger")}` },
    });
    const body = await res.json();
    expect(body.id).not.toBe("stranger");
    expect(body.data).toEqual({});
  });

  it("propagates seal errors instead of trying the next password", async () => {
    const config: SessionConfig = { name: "h3-errs", password: OLD, extraUnsealPasswords: [NEW] };
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      // 1s ttl, then the clock moves past it and the default timestamp skew
      const expired = await seal({ id: "expired", createdAt: t0, data: {} }, NEW, {
        ...sealDefaults,
        ttl: 1_000,
      });
      vi.setSystemTime(t0 + 120_000);
      await expect(unsealSession({} as any, config, expired)).rejects.toThrow("Expired seal");
      await expect(unsealSession({} as any, config, "not-a-seal")).rejects.toThrow(
        "Incorrect number of sealed components",
      );

      // maxAge is checked after opening, whichever password opened the seal
      const aged = await seal({ id: "aged", createdAt: t0, data: {} }, NEW, sealDefaults);
      await expect(
        unsealSession({} as any, { ...config, maxAge: 60 }, aged),
      ).rejects.toThrow("Session expired!");
    } finally {
      vi.useRealTimers();
    }
  });

  it("rejects an extra password shorter than 32 characters", async () => {
    const config: SessionConfig = {
      name: "h3-short",
      password: OLD,
      extraUnsealPasswords: ["curta"],
    };
    t.app.get("/short", async (event) => {
      try {
        const session = await getSession(event, config);
        return { id: session.id };
      } catch (error) {
        return { error: (error as Error).message };
      }
    });
    // Not silently treated as a new session, with or without a cookie
    const noCookie = await (await t.fetch("/short")).json();
    expect(noCookie.error).toMatch(/too short/);
    const withCookie = await t.fetch("/short", {
      headers: { Cookie: `h3-short=${await sealedWith(OLD)}` },
    });
    expect(await withCookie.json()).toMatchObject({ error: expect.stringMatching(/too short/) });
    await expect(unsealSession({} as any, config, await sealedWith(OLD))).rejects.toThrow(
      /too short/,
    );
  });

  it("does not retry a password listed as an extra", async () => {
    const foreign = await sealedWith(OTHER);
    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
    // Count key derivations for a cookie no password opens
    const attempts = async (extraUnsealPasswords: string[]) => {
      deriveBits.mockClear();
      const config: SessionConfig = { name: "h3-dedup", password: OLD, extraUnsealPasswords };
      await expect(unsealSession({} as any, config, foreign)).rejects.toThrow("Bad hmac value");
      return deriveBits.mock.calls.length;
    };
    try {
      const withDuplicate = await attempts([OLD]);
      const withoutExtras = await attempts([]);
      expect(withDuplicate).toBe(withoutExtras);
    } finally {
      deriveBits.mockRestore();
    }
  });

  it("keeps an empty extraUnsealPasswords list equivalent to none", async () => {
    const config: SessionConfig = { name: "h3-empty", password: OLD, extraUnsealPasswords: [] };
    t.app.get("/empty", async (event) => {
      const session = await getSession(event, config);
      return { id: session.id, data: session.data };
    });
    const opened = await t.fetch("/empty", {
      headers: { Cookie: `h3-empty=${await sealedWith(OLD, { foo: "bar" })}` },
    });
    expect(await opened.json()).toEqual({ id: "rot-1", data: { foo: "bar" } });
    const unknown = await t.fetch("/empty", {
      headers: { Cookie: `h3-empty=${await sealedWith(NEW)}` },
    });
    expect((await unknown.json()).id).not.toBe("rot-1");
  });

  it("reseals a legacy session opened by an extra password with the current options", async () => {
    const legacySealed = await seal(
      { id: "legacy-extra", createdAt, data: { foo: "legacy" } },
      NEW,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );
    const config: SessionConfig = {
      name: "h3-legacy-extra",
      password: OLD,
      extraUnsealPasswords: [NEW],
    };
    t.app.get("/legacy-extra", async (event) => {
      const session = await getSession(event, config);
      return { id: session.id, data: session.data };
    });
    const res = await t.fetch("/legacy-extra", {
      headers: { Cookie: `h3-legacy-extra=${legacySealed}` },
    });
    expect(await res.json()).toEqual({ id: "legacy-extra", data: { foo: "legacy" } });
    // Legacy cookie is resealed with the current password and options
    const resealed = sealedCookie(res, "h3-legacy-extra");
    await expect(unseal(resealed, OLD, sealDefaults)).resolves.toMatchObject({
      id: "legacy-extra",
      data: { foo: "legacy" },
    });
  });

  it("rejects legacy sessions opened by an extra password with legacySealFallback: false", async () => {
    const legacySealed = await seal(
      { id: "legacy-extra", createdAt, data: { foo: "legacy" } },
      NEW,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );
    const config: SessionConfig = {
      name: "h3-legacy-strict",
      password: OLD,
      extraUnsealPasswords: [NEW],
      legacySealFallback: false,
    };
    t.app.get("/legacy-strict", async (event) => {
      const session = await getSession(event, config);
      return { id: session.id, data: session.data };
    });
    const res = await t.fetch("/legacy-strict", {
      headers: { Cookie: `h3-legacy-strict=${legacySealed}` },
    });
    const body = await res.json();
    expect(body.id).not.toBe("legacy-extra");
    expect(body.data).toEqual({});
  });
});

